type EmployeeRow struct { ID int64; Name, Type string; Language *string; Reports *int }

func (r EmployeeRow) Employee() (Employee, error) {
    switch r.Type {
    case "engineer": return Engineer{ID: r.ID, Name: r.Name, Language: *r.Language}, nil
    case "manager":  return Manager{ID: r.ID, Name: r.Name, Reports: *r.Reports}, nil
    default:         return nil, fmt.Errorf("unknown employee type %q", r.Type)
    }
}
